package factory.fun;
import android.app.Activity;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.util.*;
public final class MainActivity extends Activity {


 private final int accent=0xffb45309,ink=0xff172337;
 private android.graphics.drawable.GradientDrawable shape(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private LinearLayout.LayoutParams spaced(int height,int top,int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,height);p.setMargins(0,dp(top),0,dp(bottom));return p;}
 private void hero(View v,int height){v.setBackground(shape(0xffedf2f8,20));v.setClipToOutline(true);root.addView(v,spaced(dp(height),8,12));}
 private void buzz(View v){v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);}

 private LinearLayout root;private ScrollView scroll;private TextView status;private SharedPreferences prefs;
 private String t(String en,String ko,String ja){String l=getResources().getConfiguration().getLocales().get(0).getLanguage();return "ko".equals(l)?ko:"ja".equals(l)?ja:en;}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void setup(String intro){prefs=getSharedPreferences("local",MODE_PRIVATE);scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfff6f8fc);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(18),dp(22),dp(30));scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(a.left,a.top,a.right,a.bottom);return i;});TextView title=label(getString(R.string.app_name));title.setTextSize(34);title.setTextColor(accent);title.setTypeface(null,Typeface.BOLD);label(intro);status=label(t("Ready","준비 완료","準備完了"));status.setTextColor(accent);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}
 private TextView label(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(16);v.setTextColor(ink);v.setPadding(0,dp(6),0,dp(6));root.addView(v);return v;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(48));b.setTextColor(Color.WHITE);b.setTextSize(16);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x44ffffff),shape(accent,16),null));b.setOnClickListener(v->{buzz(v);action.run();});root.addView(b,spaced(dp(52),5,5));return b;}
 private EditText edit(String name,String value){label(name);EditText e=new EditText(this);e.setContentDescription(name);e.setText(value);e.setTextColor(ink);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(shape(Color.WHITE,14));root.addView(e,spaced(-2,4,8));return e;}
 private Spinner options(String title,String... items){label(title);Spinner s=new Spinner(this);s.setContentDescription(title);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));s.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));root.addView(s,spaced(dp(48),4,8));return s;}
 private void change(Spinner s,Runnable r){s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){r.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});}

 private int unlocked,active;private int[] xp=new int[6];private boolean[] hatched=new boolean[6];private long last;private TextView pet;private Spinner select;
 private final String[] baby={"🐉","🐲","🦊","🦎","🐸","🐙"},grown={"🐲","🐉","🦁","🦖","🐊","🦑"};
 @Override public void onCreate(Bundle state){super.onCreate(state);setup(t("Hatch imaginary creatures, care for them and collect evolutions.","상상 속 몬스터를 부화시키고 돌보며 진화시켜요.","架空のモンスターを孵化・育成・進化させよう。"));unlocked=Math.max(1,Math.min(6,prefs.getInt("unlocked",1)));active=Math.max(0,Math.min(unlocked-1,prefs.getInt("active",0)));last=prefs.getLong("last",0);for(int i=0;i<6;i++){xp[i]=Rules.bound(prefs.getInt("xp"+i,0));hatched[i]=prefs.getBoolean("hatched"+i,false);}creature=new Creature(this);creature.setContentDescription(t("Your creature","나의 몬스터","モンスター"));hero(creature,295);creature.setOnClickListener(v->{buzz(v);care(1);});pet=label("");pet.setTextSize(20);select=options(t("Select creature","몬스터 선택","モンスター選択"),"1","2","3","4","5","6");select.setSelection(active);change(select,()->{int i=select.getSelectedItemPosition();if(i>=unlocked){select.setSelection(active);status.setText(t("Locked creature","아직 잠겨 있어요","未解放"));return;}active=i;save();refresh();});button(t("Hatch egg","알 부화","卵を孵化"),()->{if(!hatched[active]){hatched[active]=true;save();refresh();}});button(t("Feed +1 XP","먹이 주기 +1 XP","餌 +1 XP"),()->care(1));button(t("Play +2 XP","놀아 주기 +2 XP","遊ぶ +2 XP"),()->care(2));button(t("Unlock next egg","다음 알 해금","次の卵を解放"),()->{if(unlocked==6){status.setText(t("All unlocked","모두 해금했어요","すべて解放"));return;}if(!hatched[unlocked-1]||xp[unlocked-1]<10){status.setText(t("Evolve the previous creature first (10 XP)","이전 몬스터를 먼저 진화시키세요 (10 XP)","前のモンスターを進化させよう（10 XP）"));return;}unlocked++;active=unlocked-1;select.setSelection(active);save();refresh();});refresh();}
 private void care(int n){if(!hatched[active]){status.setText(t("Hatch the egg first","알을 먼저 부화시키세요","先に孵化させよう"));return;}long now=System.currentTimeMillis();if(now>=last&&now-last<2000){status.setText(t("Rest for a moment","잠깐 쉬어요","少し休もう"));return;}last=now;xp[active]=Rules.bound(xp[active]+n);save();refresh();}
 private void save(){SharedPreferences.Editor e=prefs.edit().putInt("unlocked",unlocked).putInt("active",active).putLong("last",last);for(int i=0;i<6;i++)e.putInt("xp"+i,xp[i]).putBoolean("hatched"+i,hatched[i]);e.apply();}
 private void refresh(){String icon=!hatched[active]?"🥚":xp[active]>=10?grown[active]:baby[active];creature.invalidate();pet.setText((!hatched[active]?t("Egg","알","卵"):xp[active]>=10?t("Evolved!","진화 완료!","進化！"):t("Baby","아기 몬스터","赤ちゃん"))+"\nXP "+xp[active]+" / 10\n"+t("Collection ","수집 ","コレクション ")+unlocked+"/6");}

 private Creature creature;
 private class Creature extends View {Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Creature(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),r=Math.min(w,h)*.26f;float x=w/2,y=h*.48f+(float)Math.sin(android.os.SystemClock.uptimeMillis()/550d)*dp(4);p.setShader(new LinearGradient(0,0,w,h,new int[]{0xffffe8b6,0xfff3c1c7,0xffd9c8ff},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);p.setColor(0x26000000);c.drawOval(x-r,y+r*.8f,x+r,y+r*1.05f,p);c.save();c.translate(x,y);int[] palette={0xff6da5dd,0xfff0a051,0xffd986ae,0xff7cbe83,0xff9d8de5,0xff5abfb9};p.setColor(palette[active]);if(!hatched[active]){c.drawOval(-r*.72f,-r,r*.72f,r,p);p.setColor(0x66ffffff);c.drawOval(-r*.49f,-r*.75f,-r*.12f,-r*.12f,p);p.setColor(0xfffef3c7);c.drawCircle(r*.2f,r*.2f,r*.19f,p);c.drawCircle(-r*.26f,r*.45f,r*.11f,p);}else{boolean evolved=xp[active]>=10;Path ear=new Path();ear.moveTo(-r*.8f,-r*.2f);ear.lineTo(-r*(evolved?1.12f:.82f),-r*1.14f);ear.lineTo(-r*.15f,-r*.62f);ear.close();c.drawPath(ear,p);c.save();c.scale(-1,1);c.drawPath(ear,p);c.restore();c.drawOval(-r,-r*.76f,r,r*.86f,p);p.setColor(0x66ffffff);c.drawOval(-r*.56f,r*.05f,r*.56f,r*.73f,p);p.setColor(Color.WHITE);c.drawOval(-r*.6f,-r*.35f,-r*.12f,r*.16f,p);c.drawOval(r*.12f,-r*.35f,r*.6f,r*.16f,p);p.setColor(0xff172337);c.drawCircle(-r*.32f,-r*.05f,r*.12f,p);c.drawCircle(r*.32f,-r*.05f,r*.12f,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(r*.055f);c.drawArc(-r*.2f,r*.15f,r*.2f,r*.39f,0,180,false,p);p.setStyle(Paint.Style.FILL);if(evolved){p.setColor(0xffffd85c);c.drawCircle(0,-r*.76f,r*.18f,p);}}c.restore();if(isShown())postInvalidateDelayed(40);}}

}
